//
// Feature: mdx-editor-ui-refinements — Vim ":w" / ":wq" Ex commands.
//
// Real-editor coverage for the Vim Ex commands wired through the reusable MDX
// editor: ":w" and ":wq" route through the same guarded submit as Ctrl/Cmd+Enter
// (Requirements 3.1, 3.2, 3.7), ":wq" additionally leaves the DDrvList edit
// state via the Close_Signal (Requirement 3.3/3.6), and the create form submits
// on ":wq" without erroring because it wires no close (Requirement 3.5).
//
// These exercise the real CodeMirror/Vim engine and the live Instagram API, so
// they belong in Cypress rather than the Bun unit suite.

import { runExCommand } from "../support/mdxEditor.js";

function ownerId() {
  return cy
    .env<{ test_users: [Cypress.TestUser, Cypress.TestUser] }>(["test_users"])
    .then(({ test_users }) => {
      const owner = test_users[0];
      if (!owner) {
        throw new Error("test_users[0] is missing");
      }
      return owner.user_id;
    });
}

// Enters Vim mode for a field and returns focus on the CodeMirror content.
function enterVimMode(fieldCy: string) {
  cy.get(`[data-cy='${fieldCy}'] [data-cy='mdx-visual-editor']`, {
    timeout: 20000,
  }).should("exist");
  cy.get(`[data-cy='${fieldCy}'] [data-cy='mdx-vim-toggle']`).click();
  cy.get(`[data-cy='${fieldCy}'] [data-cy='mdx-vim-editor']`, {
    timeout: 20000,
  }).should("exist");
  cy.get(`[data-cy='${fieldCy}'] [data-cy='mdx-vim-editor'] .cm-content`).click({
    force: true,
  });
}

// Replaces the whole document with `text` from an empty/arbitrary start, in
// insert mode, then returns to normal mode.
function replaceDocument(text: string) {
  cy.focused().type("{esc}");
  cy.focused().type("ggVGd", { delay: 0 }); // clear whole document (no-op if empty)
  cy.focused().type("i", { delay: 0 });
  cy.focused().type(text, { delay: 0, parseSpecialCharSequences: false });
  cy.focused().type("{esc}");
}

describe("Feature: mdx-editor-ui-refinements — Vim :w / :wq", () => {
  describe("create form (no close wired)", () => {
    beforeEach(() => {
      cy.viewport("iphone-6");
    });

    it(":w in Vim mode submits the create post exactly once", () => {
      cy.uniqueRecordName("post").then((postText) => {
        cy.signInAsUser(0);
        cy.intercept("POST", "/api/views/igPosts/new/item").as("createPost");
        cy.intercept("GET", "/api/views/igPosts/list/get").as("listGet");

        cy.visit("/instagreg");
        cy.waitForClerkLoaded();
        cy.get("[data-cy='igPosts_list']", { timeout: 20000 }).should("exist");
        cy.wait("@listGet");

        enterVimMode("p_text_content_field");
        replaceDocument(postText);
        runExCommand("w");

        cy.wait("@createPost").its("response.statusCode").should("eq", 202);
        cy.get("@createPost.all").should("have.length", 1);
      });
    });

    it(":wq in the create form submits and does not error (no close to perform)", () => {
      cy.uniqueRecordName("post").then((postText) => {
        cy.signInAsUser(0);
        cy.intercept("POST", "/api/views/igPosts/new/item").as("createPost");
        cy.intercept("GET", "/api/views/igPosts/list/get").as("listGet");

        cy.visit("/instagreg");
        cy.waitForClerkLoaded();
        cy.get("[data-cy='igPosts_list']", { timeout: 20000 }).should("exist");
        cy.wait("@listGet");

        enterVimMode("p_text_content_field");
        replaceDocument(postText);
        runExCommand("wq");

        cy.wait("@createPost").its("response.statusCode").should("eq", 202);
        cy.get("@createPost.all").should("have.length", 1);
      });
    });
  });

  describe("edit form (close wired to leave edit mode)", () => {
    beforeEach(() => {
      cy.viewport("iphone-6");
    });

    function seedAndOpenEdit(postText: string, patchDelayMs = 0) {
      ownerId().then((identifier) => {
        cy.task("createIgPostAsUser", {
          identifier,
          p_text_content: postText,
          p_public: true,
        });
      });

      cy.signInAsUser(0);
      cy.intercept("PATCH", "/api/views/igPosts/one/patch", (req) => {
        if (patchDelayMs > 0) {
          req.continue((res) => {
            res.setDelay(patchDelayMs);
          });
        }
      }).as("updatePost");
      cy.visit("/instagreg");

      cy.contains("[data-cy='igPosts_list'] article", postText, {
        timeout: 20000,
      })
        .find("[data-cy='ig_post_actions']")
        .click();
      cy.get("[data-cy='ig_post_edit']").click();
    }

    it(":wq submits the edit and leaves edit mode (the edit form unmounts)", () => {
      cy.uniqueRecordName("post").then((postText) => {
        seedAndOpenEdit(postText);

        enterVimMode("edit_p_text_content_field");
        replaceDocument(`## ${postText}`);
        runExCommand("wq");

        cy.wait("@updatePost").its("response.statusCode").should("eq", 202);
        // The Close_Signal left edit mode: the edit form (and its field) unmount.
        cy.get("[data-cy='edit_p_text_content_field']").should("not.exist");
        cy.get("[data-cy='ig_post_body'] h2", { timeout: 20000 }).should(
          "contain",
          postText,
        );
      });
    });

    it(":w submits the edit without the Close_Signal; the form closes only via onSuccess", () => {
      cy.uniqueRecordName("post").then((postText) => {
        // Hold the PATCH so the in-flight state is observable.
        seedAndOpenEdit(postText, 2500);

        enterVimMode("edit_p_text_content_field");
        replaceDocument(`### ${postText}`);
        runExCommand("w");

        // Contract: ":w" only submits. It does not fire the Close_Signal
        // (that is ":wq"), so while the update is in flight MutationForm
        // renders ItemEditForm's pending fallback instead of closing the edit
        // state. The edit state still always closes on mutation success
        // (ItemEditForm passes onSuccess={() => setIsEditing(false)}).
        cy.contains("Loading post content...").should("be.visible");

        cy.wait("@updatePost").its("response.statusCode").should("eq", 202);
        // onSuccess closed edit mode: the field is gone and the list shows h3.
        cy.get("[data-cy='edit_p_text_content_field']").should("not.exist");
        cy.get("[data-cy='ig_post_body'] h3", { timeout: 20000 }).should(
          "contain",
          postText,
        );
      });
    });
  });
});
